import { tv, type VariantProps } from "@/lib/beton/tv";

export const pricingTable = tv({
  slots: {
    list: "grid items-start gap-6",
    plan: "flex h-full flex-col gap-5 border-3 border-border bg-raised p-6 shadow-sm",
    badge:
      "w-fit border-3 border-border bg-primary px-2 py-0.5 font-mono text-xs font-bold tracking-widest uppercase",
    name: "font-display text-h4 font-black tracking-tight text-foreground",
    price:
      "flex flex-wrap items-baseline gap-x-1 font-display font-black tabular-nums text-foreground",
    amount: "text-h3",
    period: "font-mono text-sm font-bold",
    description: "text-pretty text-foreground",
    features: "flex flex-col gap-2",
    feature: "flex items-start gap-2 text-foreground",
    featureIcon: "mt-1 size-4 shrink-0",
    action: "pt-2",
    footnote: "font-mono text-xs font-bold",
  },
  variants: {
    columns: {
      2: { list: "sm:grid-cols-2", amount: "text-h2" },
      3: { list: "md:grid-cols-3" },
      4: { list: "sm:grid-cols-2 xl:grid-cols-4" },
    },
    featured: {
      true: { plan: "border-5 shadow-lg" },
    },
  },
  defaultVariants: {
    columns: 3,
    featured: false,
  },
});

export type PricingTableVariants = VariantProps<typeof pricingTable>;

import { pricingTable, type PricingTableVariants } from "@/lib/beton/recipes/pricing-table.recipe";
import { visuallyHidden } from "@/lib/beton/shared";
import type { ReactNode } from "react";
import { CheckIcon, MinusIcon } from "@/lib/beton/icons";
import { Section, type SectionProps } from "@/components/ui/beton/section";

export interface PricingPlan {
  /** What the plan is called. */
  name: ReactNode;
  /** The amount, already formatted. */
  price: ReactNode;
  /** What the amount is per: a month, a seat, a project. */
  period?: ReactNode;
  /** A line on who the plan is for. */
  description?: ReactNode;
  /** What is in it. Pass false as the second item to show it as missing. */
  features: (ReactNode | [ReactNode, boolean])[];
  /** The button. */
  action?: ReactNode;
  /** A word above the name, such as Most popular. */
  badge?: ReactNode;
  /** Thickens the border and drops a longer shadow. */
  featured?: boolean;
  /** Small print under the button. */
  footnote?: ReactNode;
}

export interface PricingTableProps
  extends Omit<SectionProps, "children">, Pick<PricingTableVariants, "columns"> {
  /** The plans, in order. */
  plans: PricingPlan[];
  /** The heading level of each plan. One below the section heading. */
  itemHeadingLevel?: 3 | 4 | 5;
  /** Classes for the grid itself. */
  listClassName?: string;
}

/** What each plan costs and what is in it. */
export function PricingTable({
  plans,
  columns = 3,
  itemHeadingLevel = 3,
  listClassName,
  ...props
}: PricingTableProps) {
  const Heading = `h${itemHeadingLevel}` as const;
  const list = pricingTable({ columns }).list({ class: listClassName });

  return (
    <Section {...props}>
      <ul className={list}>
        {plans.map((plan, index) => {
          const styles = pricingTable({ columns, featured: plan.featured ?? false });
          return (
            <li
              key={index}
              data-featured={plan.featured ? "" : undefined}
              className={styles.plan()}
            >
              {plan.badge ? <p className={styles.badge()}>{plan.badge}</p> : null}
              <Heading className={styles.name()}>{plan.name}</Heading>
              <p className={styles.price()}>
                <span className={styles.amount()}>{plan.price}</span>
                {plan.period ? <span className={styles.period()}>{plan.period}</span> : null}
              </p>
              {plan.description ? <p className={styles.description()}>{plan.description}</p> : null}
              <ul className={styles.features()}>
                {plan.features.map((entry, featureIndex) => {
                  const [feature, included] = Array.isArray(entry) ? entry : [entry, true];
                  return (
                    <li key={featureIndex} className={styles.feature()}>
                      {included ? (
                        <CheckIcon className={styles.featureIcon()} />
                      ) : (
                        <MinusIcon className={styles.featureIcon()} />
                      )}
                      <span className={visuallyHidden}>
                        {included ? "Included: " : "Not included: "}
                      </span>
                      <span>{feature}</span>
                    </li>
                  );
                })}
              </ul>
              {plan.action ? <div className={styles.action()}>{plan.action}</div> : null}
              {plan.footnote ? <p className={styles.footnote()}>{plan.footnote}</p> : null}
            </li>
          );
        })}
      </ul>
    </Section>
  );
}
